using DriveOS.Application.Abstractions.Authentication; using DriveOS.Application.Abstractions.Messaging; using DriveOS.Application.Abstractions.Persistence; using DriveOS.Modules.Organizations.Domain.OrganizationRepresentatives; using DriveOS.SharedKernel.Results;
namespace DriveOS.Modules.Organizations.Application.OrganizationRepresentatives.Suspend;
internal sealed class SuspendOrganizationRepresentativeCommandHandler(IOrganizationRepresentativeRepository repository,IUnitOfWork unitOfWork,ICurrentUser currentUser):ICommandHandler<SuspendOrganizationRepresentativeCommand>{public async Task<Result> Handle(SuspendOrganizationRepresentativeCommand c,CancellationToken ct){if(!currentUser.IsAuthenticated||currentUser.UserId is null)return Result.Failure(OrganizationRepresentativeErrors.CurrentUserRequired);var e=await repository.GetForUpdateAsync(c.RepresentativeId,c.OrganizationId,ct);if(e is null)return Result.Failure(OrganizationRepresentativeErrors.NotFound);if(e.Revision!=c.ExpectedRevision)return Result.Failure(OrganizationRepresentativeErrors.ConcurrentUpdate);var r=e.Suspend(c.Reason,currentUser.UserId.Value);if(r.IsFailure)return r;await unitOfWork.CommitAsync(ct);return Result.Success();}}
